-- ADR-035: Personalizado's modules and limits that start with it, and add-ons the operator gives
-- without charge. Checks over rows under forced RLS need system context (mistake 20).
SELECT set_config('app.rls_system', 'on', true);--> statement-breakpoint
ALTER TABLE "audit_events" DROP CONSTRAINT "audit_events_action_check";--> statement-breakpoint
ALTER TABLE "subscription_items" ADD COLUMN "starts_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "subscription_items" ADD COLUMN "complimentary" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "subscription_items" ADD COLUMN "complimentary_reason" text;--> statement-breakpoint
ALTER TABLE "audit_events" ADD CONSTRAINT "audit_events_action_check" CHECK (action IN ('organization.created', 'organization.went_live', 'organization.two_factor_requirement_changed', 'organization.settings_changed', 'branch.created', 'branch.updated', 'issue_point.created', 'issue_point.document_types_changed', 'issue_point.paused_changed', 'sequence.starting_set', 'certificate.uploaded', 'member.invited', 'member.invitation_revoked', 'member.joined', 'member.role_changed', 'member.removed', 'member.issue_points_changed', 'agreements.accepted', 'session.started', 'subscription.plan_changed', 'subscription.billing_changed', 'subscription.price_changed', 'subscription.module_added', 'subscription.module_removed', 'subscription.limit_set', 'subscription.limit_cleared', 'entitlements.override_set', 'entitlements.override_cleared', 'payment.created', 'payment.reported', 'payment.cancelled', 'payment.verified', 'payment.rejected', 'payment.refunded', 'subscription.change_scheduled', 'subscription.cancelled', 'subscription.resumed', 'organization.suspended', 'organization.reactivated', 'subscription.renewal_due', 'subscription.grace_started', 'subscription.past_due', 'subscription.moved_to_free', 'payment.card_duplicate', 'payment.invoiced', 'payment.card_resolved', 'payment.repriced', 'subscription.custom_billing_started', 'subscription.moved_to_custom', 'subscription.module_complimentary'));--> statement-breakpoint
ALTER TABLE "subscription_items" ADD CONSTRAINT "subscription_items_complimentary_check" CHECK (complimentary = (complimentary_reason IS NOT NULL) AND (NOT complimentary OR kind = 'MODULE'));--> statement-breakpoint
SELECT set_config('app.rls_system', '', true);
